collisions = {}

# Iterate over all 1000 possible triples (x, y, z)
for x in range(10):
    for y in range(10):
        for z in range(10):
            # Calculate the response vector (V1, V2)
            v1 = V(x, y, z, Q1[0], Q1[1], Q1[2])
            v2 = V(x, y, z, Q2[0], Q2[1], Q2[2])
            response = (v1, v2)

            if response in collisions:
                # Collision found!
